const body = $input.first().json.body || $input.first().json;
const toolCallList = body?.message?.toolCallList || [];
const toolCall = toolCallList[0] || {};
const toolCallId = toolCall.id || 'unknown';
let args = {};
try { args = JSON.parse(toolCall.function?.arguments || '{}'); } catch(e) { args = {}; }
return [{ json: { toolCallId, phone: args.phone || '', appointmentId: args.appointmentId || null, reason: args.reason || 'Belirtilmedi' } }];

const toolCallId = $('Argümanları Çıkar').first().json.toolCallId;
const cancelled = $('Randevu İptal Et').all().map(i => i.json).filter(r => r.id);
if (cancelled.length === 0) {
  return [{ json: { toolCallId, result: 'Aktif randevunuz bulunamadı. Lütfen telefon numaranızı kontrol edin.' } }];
}
return [{ json: { toolCallId, result: 'Randevunuz başarıyla iptal edildi. Başka bir konuda yardımcı olabilir miyim?' } }];
